def get_product_by_asin(asin, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0559000" if __import__("os").path.isdir("./environment_mix/0559000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix="req"):
        # Deterministic enough for local store; avoids non-stdlib deps
        return f"{prefix}_{int(time.time() * 1000)}"

    t0 = time.time()
    endpoint = "get_product_by_asin"
    status = "ok"
    error_obj = None
    response_obj = None

    # --- Validate input first ---
    if not isinstance(asin, str):
        status = "error"
        error_obj = _err("VALIDATION_ERROR", "asin must be a string.")
    else:
        asin_s = asin.strip()
        if not asin_s:
            status = "error"
            error_obj = _err("VALIDATION_ERROR", "asin is required and must not be empty.")
        else:
            # ASINs are typically 10 chars, alphanumeric; enforce this since the API refuses invalid ASIN strings
            if not re.fullmatch(r"[A-Z0-9]{10}", asin_s.upper()):
                status = "error"
                error_obj = _err("VALIDATION_ERROR", "asin is not a valid ASIN string (expected 10 alphanumeric characters).")
            else:
                asin_s = asin_s.upper()

    # --- Load collections (schema not provided; search real JSON files) ---
    # We'll search all JSON collections for a row with asin == requested.
    product_row = None
    product_source = None
    if error_obj is None:
        try:
            files = []
            for fn in os.listdir(_DB):
                if fn.lower().endswith(".json"):
                    files.append(fn)
        except Exception:
            files = []

        # Prefer likely product collections first
        preferred = []
        for cand in ("products.json", "product.json", "catalog.json", "items.json", "amazon_products.json"):
            if cand in files:
                preferred.append(cand)
        others = [f for f in files if f not in preferred]
        search_order = preferred + sorted(others)

        def _iter_rows(data):
            if isinstance(data, list):
                for r in data:
                    if isinstance(r, dict):
                        yield r
            elif isinstance(data, dict):
                # common patterns: {"data":[...]} or {"items":[...]}
                for k in ("data", "items", "rows", "products", "results"):
                    v = data.get(k)
                    if isinstance(v, list):
                        for r in v:
                            if isinstance(r, dict):
                                yield r

        for fn in search_order:
            data = _load(fn)
            for r in _iter_rows(data):
                a = r.get("asin")
                if isinstance(a, str) and a.strip().upper() == asin_s:
                    product_row = r
                    product_source = fn
                    break
            if product_row is not None:
                break

        if product_row is None:
            status = "error"
            error_obj = _err("NOT_FOUND", "No product found for the provided ASIN.", asin=asin_s)

    # --- Ensure audit/usage recording exists and is updated on every call (reads included) ---
    # Since schema doesn't declare collections, we create/maintain service dynamics files:
    # - usage.json: append-only request log
    # - counters.json: aggregate counters used by quota/rate enforcement
    usage_file = "usage.json"
    counters_file = "counters.json"

    usage = _load(usage_file)
    if not isinstance(usage, list):
        usage = []

    counters = _load(counters_file)
    if not isinstance(counters, dict):
        counters = {}

    # --- Rate limit / quota enforcement based on stored usage ---
    # Conservative defaults (since none declared): 120 req/min and 10,000 req/day
    rate_per_min = counters.get("rate_limit_per_minute", 120)
    quota_per_day = counters.get("quota_limit_per_day", 10000)

    now = datetime.datetime.utcnow()
    minute_ago = now - datetime.timedelta(seconds=60)
    day_ago = now - datetime.timedelta(days=1)

    def _parse_ts(ts):
        if not isinstance(ts, str):
            return None
        try:
            if ts.endswith("Z"):
                ts = ts[:-1]
            return datetime.datetime.fromisoformat(ts)
        except Exception:
            return None

    recent_1m = 0
    recent_24h = 0
    for e in usage:
        if not isinstance(e, dict):
            continue
        ts = _parse_ts(e.get("timestamp"))
        if ts is None:
            continue
        if ts >= minute_ago:
            recent_1m += 1
        if ts >= day_ago:
            recent_24h += 1

    # Enforce before finalizing response; even rejected requests are recorded, but limits must block service
    if error_obj is None:
        if isinstance(rate_per_min, int) and rate_per_min >= 0 and recent_1m >= rate_per_min:
            status = "error"
            error_obj = _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit_per_minute=rate_per_min)
        elif isinstance(quota_per_day, int) and quota_per_day >= 0 and recent_24h >= quota_per_day:
            status = "error"
            error_obj = _err("QUOTA_EXCEEDED", "Daily quota exceeded. Please retry later.", quota_per_day=quota_per_day)

    # --- Build response envelope ---
    if error_obj is not None:
        response_obj = error_obj
    else:
        # Return product details; never fabricate fields, return stored row
        response_obj = {
            "product": product_row,
            "meta": {
                "asin": asin_s,
                "source_collection": product_source,
            },
        }

    # --- Record request to usage log and advance counters (always, even errors) ---
    latency_ms = int((time.time() - t0) * 1000)
    req_row = {
        "id": _gen_id("req"),
        "endpoint": endpoint,
        "timestamp": _now(),
        "status": "error" if "error" in response_obj else "ok",
        "latency_ms": latency_ms,
        "asin": asin if isinstance(asin, str) else None,
    }
    usage.append(req_row)

    # Advance counters
    counters["total_requests"] = int(counters.get("total_requests", 0) or 0) + 1
    if "error" in response_obj:
        counters["total_errors"] = int(counters.get("total_errors", 0) or 0) + 1
        code = response_obj["error"].get("code")
        if code:
            per_code = counters.get("errors_by_code", {})
            if not isinstance(per_code, dict):
                per_code = {}
            per_code[code] = int(per_code.get(code, 0) or 0) + 1
            counters["errors_by_code"] = per_code
    else:
        counters["total_success"] = int(counters.get("total_success", 0) or 0) + 1

    counters["last_request_timestamp"] = req_row["timestamp"]
    counters["last_request_latency_ms"] = latency_ms
    counters["last_endpoint"] = endpoint

    _save(usage_file, usage)
    _save(counters_file, counters)

    return response_obj
